  rep(rs,"#[tauri::command]\nfn alec_panel_compact(app: AppHandle, compact: bool) -> Result<(), String> {\n    let w = app.get_webview_window(PANEL_LABEL).ok_or(\"ALEC panel unavailable\")?;\n    let m = w.current_monitor().map_err(|e| e.to_string())?.or_else(|| app.primary_monitor().ok().flatten()).ok_or(\"Monitor unavailable\")?;\n    let s = m.scale_factor();\n    let a = m.work_area();\n    let width = ((if compact { 380.0 } else { PANEL_W }) * s).min((a.size.width as f64 - 16.0*s).max(240.0));\n    let height = ((if compact { 470.0 } else { PANEL_H }) * s).min((a.size.height as f64 - 16.0*s).max(240.0));\n    set_panel_size(&w, width, height, s);\n    let x = if compact { a.position.x as f64 + a.size.width as f64 - width - 12.0*s } else { a.position.x as f64 + (a.size.width as f64 - width)/2.0 };\n    let y = if compact { a.position.y as f64 + a.size.height as f64 - height - 12.0*s } else { a.position.y as f64 + (a.size.height as f64 - height)/2.0 };\n    set_panel_position(&w,x,y,s);\n    w.set_always_on_top(compact).map_err(|e|e.to_string())?;\n    ALEC_PANEL_COMPACT.store(compact, Ordering::SeqCst);\n    let _ = w.eval(format!(\"window.__alecSetCompact?.({})\", compact));\n    let _ = w.set_focus();\n    Ok(())\n}\n#[tauri::command]\nfn alec_panel_compact_state() -> bool {\n    ALEC_PANEL_COMPACT.load(Ordering::SeqCst)\n}\n#[tauri::command]\nfn alec_orb_open(app: AppHandle, compact: bool) -> Result<(), String> {\n    show_panel(&app, None, false);\n    alec_panel_compact(app, compact)\n}\n#[tauri::command]\nfn panel_hide(app: AppHandle) {","#[tauri::command]\nfn alec_orb_open(app: AppHandle, compact: bool) -> Result<(), String> {\n    let _ = compact;\n    show_panel(&app, None, false);\n    Ok(())\n}\n#[tauri::command]\nfn panel_hide(app: AppHandle) {");
