  rep(sc,"function checkUpdates(manual = false) {\n  update.manual = manual;\n  if (manual) { update.checking = true; update.result = null; panel(); }\n  send({ type: 'update', install: false });\n}\nfunction installUpdate() {\n  if (update.installing) return;\n  update.installing = true; menu();\n  send({ type: 'update', install: true });\n}\n","let alecRelease = null;\nasync function checkUpdates(manual = false) {\n  if(update.checking)return;\n  update.manual=manual;update.checking=true;update.result=null;panel();\n  try{\n    const release=await checkAlecRelease(VERSION);\n    alecRelease=release.state==='available'?release:null;\n    update.available=alecRelease?.version||null;update.page=!!alecRelease;\n    update.result={ok:true,at:Date.now()};\n    if(alecRelease&&(manual||update.told!==alecRelease.version)){\n      update.told=alecRelease.version;panelNote('ALEC '+alecRelease.version+' disponível. Consulta Novidades.');\n      if(!manual) say('ALEC '+alecRelease.version+' está disponível. Abre Novidades para instalar e reiniciar.', 'happy');\n    }else if(manual)panelNote(release.state==='no-release'?'Ainda não existe uma versão publicada.':'O ALEC está actualizado.');\n  }catch{update.result={ok:false,error:'Não foi possível consultar as actualizações ALEC.'};if(manual)panelNote(update.result.error,true);}\n  finally{update.checking=false;update.manual=false;menu();panel();}\n}\nfunction installUpdate() {\n  // Until a dedicated signed update feed is provisioned, only the official release page can be opened.\n  if(alecRelease&&alecRelease.version===update.available)openUrl(alecRelease.url);\n  else void checkUpdates(true);\n}\n");
