  rep(ja,"   const count=R<32?220:R<60?420:N;","   // ALEC_PLASMA_V6: animated electronic gas inside the SAME sphere.\n   // Clipped to the core, independent of the surrounding V5 halo. Additive light, no second sphere.\n   const voiceActive=mode==='talk'||mode==='listen', processing=mode==='think'||mode==='execute';\n   const plasmaEnergy=voiceActive?.30+.70*level:processing?.62:.26;\n   const flow=clock*(processing?1.8:voiceActive?1.35:.55);\n   ctx.save();\n   try {\n    ctx.beginPath();ctx.arc(cx,cy,R*.92,0,TAU);ctx.clip();\n    ctx.globalCompositeOperation='lighter';\n    const lobes=st.reduced?4:R<35?5:9;\n    for(let i=0;i<lobes;i++){\n     const ph=i*2.399963,a=ph+flow*(.23+.045*(i%3));\n     const wobble=.5+.5*Math.sin(flow*.81+ph*2);\n     const d=R*(.12+.36*wobble+.07*plasmaEnergy);\n     const x=cx+Math.cos(a)*d,y=cy+Math.sin(a*1.13+ph)*d*.82;\n     const r=R*(.25+.26*wobble+.16*plasmaEnergy);\n     const col=i%3===0?'135,110,255':i%3===1?'72,150,255':'156,206,255';\n     const alpha=(.14+.34*plasmaEnergy)*(.65+.35*wobble);\n     const g=ctx.createRadialGradient(x,y,0,x,y,r);\n     g.addColorStop(0,'rgba('+col+','+alpha+')');g.addColorStop(.30,'rgba('+col+','+(alpha*.68)+')');\n     g.addColorStop(.70,'rgba('+col+','+(alpha*.15)+')');g.addColorStop(1,'rgba('+col+',0)');\n     ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2);\n    }\n    const strands=st.reduced?2:R<35?3:5,samples=R<35?18:30;\n    for(let i=0;i<strands;i++){\n     const ph=i*TAU/strands+flow*.22;\n     ctx.beginPath();\n     for(let j=0;j<=samples;j++){\n      const u=j/samples,a=ph+u*Math.PI*1.5;\n      const r=R*(.27+.31*Math.sin(u*Math.PI)+.08*Math.sin(a*3-flow*1.3)+.09*plasmaEnergy*Math.sin(u*TAU*2-flow*2));\n      const x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r;j?ctx.lineTo(x,y):ctx.moveTo(x,y);\n     }\n     ctx.lineCap='round';ctx.lineJoin='round';\n     ctx.lineWidth=Math.max(.7,R*.054);ctx.strokeStyle='rgba(70,123,255,'+(.045+.15*plasmaEnergy)+')';ctx.stroke();\n     ctx.lineWidth=Math.max(.4,R*.012);ctx.strokeStyle='rgba(174,210,255,'+(.10+.32*plasmaEnergy)+')';ctx.stroke();\n    }\n   }finally{ctx.restore();}\n   const count=R<32?220:R<60?420:N;");
