  rep(rs,"fn upstream_update_disabled(app: &AppHandle, install: bool) {","fn alec_signed_update(app: &AppHandle, tag: &str) {\n    use tauri_plugin_updater::UpdaterExt;\n    if !cfg!(target_os = \"windows\") || !ALEC_SIGNED_UPDATE {\n        to_sidecar(app, &json!({\"type\":\"alec_signed_update_status\",\"state\":\"error\",\"error\":\"Actualizador assinado indisponível.\"})); return;\n    }\n    let version = tag.strip_prefix('v').unwrap_or(\"\");\n    let parts: Vec<&str> = version.split('.').collect();\n    if parts.len()!=3 || parts.iter().any(|p| p.is_empty() || p.len()>9 || !p.bytes().all(|b| b.is_ascii_digit()) || (p.len()>1 && p.starts_with('0'))) {\n        to_sidecar(app, &json!({\"type\":\"alec_signed_update_status\",\"state\":\"error\",\"error\":\"Versão inválida.\"})); return;\n    }\n    if ALEC_UPDATING.swap(true, Ordering::SeqCst) { return; }\n    let app=app.clone();\n    let expected=version.to_string();\n    let endpoint=format!(\"https://github.com/Mula-Edmilson/alec-ola-alec-build/releases/download/{tag}/latest.json\");\n    tauri::async_runtime::spawn(async move {\n        let status=|state:&str,error:&str| to_sidecar(&app,&json!({\"type\":\"alec_signed_update_status\",\"state\":state,\"error\":error,\"version\":expected}));\n        let result: Result<(),String> = async {\n            let url=endpoint.parse().map_err(|_|\"URL inválido.\".to_string())?;\n            let updater=app.updater_builder().endpoints(vec![url]).map_err(|e|e.to_string())?.build().map_err(|e|e.to_string())?;\n            let update=updater.check().await.map_err(|e|e.to_string())?.ok_or(\"Nenhuma actualização mais recente disponível.\".to_string())?;\n            if update.version!=expected { return Err(\"A versão do manifesto não corresponde à release.\".into()); }\n            status(\"downloading\",\"\");\n            update.download_and_install(|_,_|{},||{}).await.map_err(|e|e.to_string())?;\n            Ok(())\n        }.await;\n        ALEC_UPDATING.store(false,Ordering::SeqCst);\n        match result { Ok(())=>{status(\"installed\",\"\");tokio_sleep(Duration::from_millis(1500)).await;app.restart();}, Err(e)=>status(\"error\",&e) }\n    });\n}\nstatic ALEC_UPDATING: AtomicBool=AtomicBool::new(false);\n#[allow(dead_code)]\nfn upstream_update_disabled(app: &AppHandle, install: bool) {");
